BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap;
SET LOCAL search_path=public,private,auth,extensions,pg_temp;
SELECT plan(25);
SELECT has_table('public','quote_decisions','Commercial decision is separate from issued snapshots');
SELECT has_table('public','portal_payment_contexts','Return capability is a dedicated encrypted context');
SELECT col_not_null('public','quote_decisions','org_id','Decision requires tenant');
SELECT col_not_null('public','portal_payment_contexts','org_id','Return requires tenant');
SELECT ok((SELECT relrowsecurity FROM pg_class WHERE oid='public.quote_decisions'::regclass),'Decision enforces RLS');
SELECT ok((SELECT relrowsecurity FROM pg_class WHERE oid='public.portal_payment_contexts'::regclass),'Return enforces RLS');
SELECT has_column('public','quote_decisions','selected_version_id','Chosen full snapshot is referenced');
SELECT has_column('public','quote_decisions','offering_version_id','Offer and chosen snapshot are distinct references');
SELECT has_column('public','quote_decisions','position_id','Change points to a sealed position');
SELECT has_column('public','quote_decisions','evidence','Consent evidence is retained');
SELECT has_column('public','portal_payment_contexts','access_hash','Return access is hashed');
SELECT has_column('public','portal_payment_contexts','token_ciphertext','Portal token is encrypted');
SELECT ok(NOT has_table_privilege('anon','public.quote_decisions','SELECT'),'Anonymous role cannot read decisions');
SELECT ok(NOT has_table_privilege('authenticated','public.quote_decisions','INSERT'),'Authenticated role cannot forge decisions');
SELECT ok(NOT has_column_privilege('portal_backend','public.quote_decisions','evidence','SELECT'),'Public portal cannot read personal evidence');
SELECT ok(has_column_privilege('documentary_backend','public.quote_decisions','evidence','SELECT'),'Commercial backend reads evidence under RLS');
SELECT ok(NOT has_table_privilege('portal_backend','public.portal_payment_contexts','SELECT'),'Public portal role cannot enumerate return capabilities');
SELECT ok(NOT has_table_privilege('authenticated','public.portal_payment_contexts','SELECT'),'Browser tenants cannot read ciphertext');
SELECT ok(NOT has_table_privilege('documentary_backend','public.quote_decisions','UPDATE') AND NOT has_table_privilege('portal_backend','public.quote_decisions','DELETE'),'No backend grant rewrites consent');
SELECT ok(EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='public.quote_decisions'::regclass AND tgname='quote_decision_guard'),'Decision scope and immutability guard exists');
SELECT ok(EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='public.quote_decisions'::regclass AND tgname='quote_decision_no_truncate'),'Decision cannot be truncated');
SELECT ok(EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='public.portal_payment_contexts'::regclass AND tgname='portal_payment_context_no_truncate'),'Return cannot be truncated');
SELECT ok(NOT has_function_privilege('anon','private.quotation_choice(uuid,uuid)','EXECUTE') AND has_function_privilege('documentary_backend','private.quotation_choice(uuid,uuid)','EXECUTE'),'Nonpersonal choice is scoped to authorized consumers');
SELECT ok(EXISTS(SELECT 1 FROM pg_constraint WHERE conrelid='public.quote_decisions'::regclass AND contype='u' AND pg_get_constraintdef(oid)='UNIQUE (org_id, offering_version_id)'),'Only one human response can win per offer');
SELECT ok(NOT has_function_privilege('anon','private.quote_has_conflicting_invoice(uuid,uuid,uuid)','EXECUTE') AND has_function_privilege('portal_backend','private.quote_has_conflicting_invoice(uuid,uuid,uuid)','EXECUTE'),'Invoice conflict projection is private and capability scoped');
SELECT * FROM finish();
ROLLBACK;
